(function() {

  let initAttempts = 0;
  const maxAttempts = 40;
  const checkInterval = 500;
  const checkIntervalId = setInterval(() => {
    initAttempts++;
    const parentWin = typeof window.parent !== 'undefined' ? window.parent : window;
    if (parentWin.jQuery && parentWin.SillyTavern && parentWin.TavernHelper) {
      clearInterval(checkIntervalId);
      const $ = parentWin.jQuery;
      console.log('核心API (包括TavernHelper) 已就绪，开始初始化模块...');

      $(parentWin.document).ready(function () {
        // 在当前页面添加一个固定的、用于播放背景音乐的iframe播放器。
        // 检查是否已存在播放器，避免重复添加
        if (parentWin.document.getElementById('demon-king-bgm-player')) {
            console.log('[内嵌播放器] 错误：播放器已存在。无需重复注册。');
            return;
        }

        // 1. 创建iframe元素
        const musicFrame = parentWin.document.createElement('iframe');

        // 2. 设定其核心属性
        musicFrame.id = 'demon-king-bgm-player'; // 赋予其唯一ID，便于管理
        musicFrame.src = "//music.163.com/outchain/player?type=3&id=1366366173&auto=1&height=66";
        musicFrame.width = "330";
        musicFrame.height = "86";
        musicFrame.setAttribute('frameborder', 'no');
        musicFrame.setAttribute('border', '0');
        musicFrame.setAttribute('marginwidth', '0');
        musicFrame.setAttribute('marginheight', '0');

        // 3. 设计其样式与位置
        musicFrame.style.cssText = `
            position: fixed;
            right: 20px;
            bottom: 20px;
            z-index: 10000;
            border-radius: 12px;
            box-shadow: 0 0 20px rgba(138, 77, 255, 0.5);
            opacity: 0.85;
            transition: opacity 0.3s ease;
        `;
        // 添加鼠标悬停时变清晰的效果，以更好地融入UI
        musicFrame.onmouseover = () => { musicFrame.style.opacity = '1'; };
        musicFrame.onmouseout = () => { musicFrame.style.opacity = '0.85'; };


        // 4. 在酒馆内注册iframe元素
        parentWin.document.body.appendChild(musicFrame);

        console.log('[内嵌播放器] 内嵌成功！背景音乐已播放。');
      });
    } else if (initAttempts > maxAttempts) {
      clearInterval(checkIntervalId);
      logError('初始化超时，未能加载SillyTavern核心API(特别是TavernHelper)。脚本将无法工作。');
    }
  }, checkInterval);

})();

