                    return false; // 没有消耗，永远不会因资源不足而禁用
                }

                // 解析costText字符串以获取消耗
                // 这是一个简化的解析，未来可由更标准的cost对象代替
                // 例如 "魔晶200, 魂魄20"
                const costs = button.costText.split(',');
                for (const costStr of costs) {
                    const trimmedCost = costStr.trim();
                    if (trimmedCost.includes('魔晶')) {
                        const amount = parseInt(trimmedCost.replace(/[^0-9]/g, ''));
                        if (snapshot.playerState.resources.magicCrystal < amount) return true;
                    } else if (trimmedCost.includes('魂魄')) {
                        const amount = parseInt(trimmedCost.replace(/[^0-9]/g, ''));
                        if (snapshot.playerState.resources.soulEssence < amount) return true;
                    } else if (trimmedCost.includes('堕落精华')) {
                        const amount = parseInt(trimmedCost.replace(/[^0-9]/g, ''));
                        if (snapshot.playerState.resources.corruptionEssence < amount) return true;
                    }
                }

                // 如果所有资源检查都通过，则按钮可用
                return false;
            };

            const sendToAI = (payload) => {
                if (isWaitingForAI.value) return;
                isWaitingForAI.value = true;
                console.log("向AI发送指令:", payload);
                // 这里是与sillytavern_connector.js通信的地方
                // parent.postMessage({ type: 'DEMON_KING_ACTION', payload }, '*');
                // 调用sillytavern指令
                triggerSlash('/send ' + '[玩家指令] 类型: ' + payload.type + ', 目标: ' + payload.id + '|/trigger');
            };

            const handleActionClick = (button) => {
                const buttonType = button.type || 'action';

                switch(buttonType) {
                    case 'ui_static':
                        if (button.id === 'open_map') uiState.isMapVisible = true;
                        break;
                    case 'ui_category': // 进入下一级（从模块到次级分类）
                    case 'category': // 进入下一级（从根到模块）
                        uiState.viewPath.push(button.id);
                        break;
                    case 'ui_back':
                        uiState.viewPath.pop();
                        break;
                    case 'action':
                    default:
                        sendToAI({ type: buttonType , id: button.id, name: button.name });
                        break;
                }
            };

            // --- AI数据更新 ---
            window.addEventListener('message', (event) => {
                if (event.data && event.data.type === 'UPDATE_DEMON_KING_UI') {
                    // ... 更新snapshot数据的代码 ...

                    // [!] 核心修改：在UI更新完毕后，宣告世界“沉思”结束，解除所有按钮的锁定
                    isWaitingForAI.value = false;
                }
            });

            return { snapshot, uiState, isWaitingForAI, logDisplay, breadcrumb, currentActions, handleActionClick, getResourceName, isButtonDisabled, getToastMessage/* ... */ };
        }
    }).mount('#app');
</script>
</body>
</html>
