(function() {

    const assistantId = 'demon-king-sprite-assistant';
    const chatBubbleId = 'demon-king-sprite-chat-bubble';

    // 定义Albin可能说的话
    const albinQuotes = [
        "陛下，您的意志，世界必将回应。",
        "一切尽在您的掌握之中，魔王大人。",
        "法则正在为您效力。",
        "好戏，即将开场。",
        "Albin在此，静候您的下一步敕令。"
    ];

    // --- 灵体召唤术 v1.0 ---
    // 用途: 在当前页面生成一个可拖动的、代表“系统精灵小助手”的图标。
    const assistantCall = (parentWin) => {
        // 检查灵体是否已被召唤
        if (parentWin.document.getElementById(assistantId)) {
            console.log('[灵体召唤术] 错误：Albin已在您的身边。');
            return;
        }

        // --- 步骤一：塑造灵体的形态 (创建DIV并应用CSS) ---
        const assistantIcon = parentWin.document.createElement('div');
        assistantIcon.id = assistantId;

        // 创建并注入样式
        const style = parentWin.document.createElement('style');
        style.innerHTML = `
            @keyframes pulse {
                0% { box-shadow: 0 0 10px rgba(0, 242, 234, 0.4), 0 0 5px rgba(138, 77, 255, 0.3); }
                50% { box-shadow: 0 0 20px rgba(0, 242, 234, 0.8), 0 0 10px rgba(138, 77, 255, 0.6); }
                100% { box-shadow: 0 0 10px rgba(0, 242, 234, 0.4), 0 0 5px rgba(138, 77, 255, 0.3); }
            }
            #${assistantId} {
                position: fixed;
                left: 20%;
                top: 10%;
                transform: translateY(-50%);
                width: 60px;
                height: 60px;
                background-image: url('https://ooo.0x0.ooo/2025/09/08/OlZACD.png');
                background-size: contain;
                background-repeat: no-repeat;
                background-position: center;
                border-radius: 50%;
                border: 2px solid rgba(0, 242, 234, 0.7);
                cursor: move;
                z-index: 10001; /* 比音乐播放器更高一层 */
                animation: pulse 3s infinite ease-in-out;
                transition: transform 0.2s ease-out;
            }
            #${assistantId}:active {
                cursor: grabbing;
                transform: translateY(-50%) scale(1.1);
                filter: brightness(1.2);
            }
        `;
        parentWin.document.head.appendChild(style);

        // --- 步骤二：赋予灵体移动的权能 (拖动逻辑) ---
        let isDragging = false;
        let offsetX, offsetY;

        assistantIcon.addEventListener('mousedown', (e) => {
            // 阻止默认的拖拽行为，如拖拽图片
            e.preventDefault();

            isDragging = true;
            // 计算鼠标点击位置与图标左上角的偏移量
            offsetX = e.clientX - assistantIcon.getBoundingClientRect().left;
            offsetY = e.clientY - assistantIcon.getBoundingClientRect().top;

            // 为整个文档添加移动和松开的监听器
            parentWin.document.addEventListener('mousemove', onMouseMove);
            parentWin.document.addEventListener('mouseup', onMouseUp);
        });

        function onMouseMove(e) {
            if (!isDragging) return;
            // 根据鼠标位置和偏移量，计算图标的新位置
            let newLeft = e.clientX - offsetX;
            let newTop = e.clientY - offsetY;

            // 边界检测，防止图标被拖出屏幕
            const rect = parentWin.document.body.getBoundingClientRect();
            newLeft = Math.max(0, Math.min(newLeft, rect.width - assistantIcon.offsetWidth));
            newTop = Math.max(0, Math.min(newTop, rect.height - assistantIcon.offsetHeight));

            assistantIcon.style.left = newLeft + 'px';
            assistantIcon.style.top = newTop + 'px';
            assistantIcon.style.transform = ''; // 清除transform以正确定位
        }

        function onMouseUp() {
            isDragging = false;
            // 拖动结束，移除全局监听器
            parentWin.document.removeEventListener('mousemove', onMouseMove);
            parentWin.document.removeEventListener('mouseup', onMouseUp);
        }

        // 步骤三：为灵体注入交互的可能 (点击事件)
        assistantIcon.addEventListener('click', (e) => {
            // 如果是拖动结束时的那次click，则不触发
            if (Math.abs(e.clientX - (assistantIcon.getBoundingClientRect().left + offsetX)) > 5) return;
            if (Math.abs(e.clientY - (assistantIcon.getBoundingClientRect().top + offsetY)) > 5) return;

            console.log('[系统精灵] Albin在此，陛下有何吩咐？');
            // 未来可以在此处触发更复杂的功能
        });

        // --- 步骤四：将灵体召唤至当前世界 ---
        parentWin.document.body.appendChild(assistantIcon);
        console.log('[灵体召唤术] 咏唱成功！您的专属助手Albin已具现化。');
    }

  let initAttempts = 0;
  const maxAttempts = 40;
  const checkInterval = 500;
