                console.error('[灵体赋声术] 错误：未找到Albin的灵体。请先执行“灵体召唤术”。');
                return;
            }

            // --- 步骤二：定义回应的言灵 (CSS样式) ---
            const style = parentWin.document.createElement('style');
            style.innerHTML = `
                @keyframes bubble-fade-in-out {
                    0% { opacity: 0; transform: scale(0.8); }
                    15% { opacity: 1; transform: scale(1); }
                    85% { opacity: 1; transform: scale(1); }
                    100% { opacity: 0; transform: scale(0.8); }
                }
                #${chatBubbleId} {
                    position: fixed;
                    padding: 10px 15px;
                    background-color: rgba(18, 13, 48, 0.9);
                    border: 1px solid var(--highlight-color, #00f2ea);
                    color: var(--text-color, #e0e0e0);
                    border-radius: 10px;
                    box-shadow: 0 0 15px rgba(0, 242, 234, 0.5);
                    font-family: var(--font-main, 'Noto Sans SC', sans-serif);
                    font-size: 14px;
                    max-width: 200px;
                    z-index: 10002; /* 比助手图标更高一层 */
                    animation: bubble-fade-in-out 4s ease-in-out forwards;
                    white-space: normal;
                }
                #${chatBubbleId}::after {
                    content: '';
                    position: absolute;
                    bottom: 10px;
                    left: -10px; /* 指向左侧的助手图标 */
                    width: 0;
                    height: 0;
                    border-style: solid;
                    border-width: 8px 10px 8px 0;
                    border-color: transparent var(--highlight-color, #00f2ea) transparent transparent;
                }
            `;
            parentWin.document.head.appendChild(style);
            // 监听事件和小精灵对话
            const showChatBubble = (messageId) => {
                const assistantIcon = parentWin.document.getElementById(assistantId);
                // 先移除旧的气泡
                const existingBubble = parentWin.document.getElementById(chatBubbleId);
                if (existingBubble) {
                    existingBubble.parentNode.removeChild(existingBubble);
                }

                // 创建新的气泡
                const chatBubble = parentWin.document.createElement('div');
                chatBubble.id = chatBubbleId;

                // 随机选择一句话
                chatBubble.textContent = albinQuotes[Math.floor(Math.random() * albinQuotes.length)];

                // 获取该对话的信息
                const messages = parentWin.TavernHelper.getChatMessages(messageId, { include_swipes: false });
                // TODO 解析该对话
                const regexGlobal = /\"message\":\"([\s\S]*?)\"/g;
                const messageJson = JSON.stringify(messages[0].message).replace(/[\\n]/g, "").replace(/[ ]/g, "").match(regexGlobal);
                if (messageJson != null && messageJson != "") {
                    chatBubble.textContent = JSON.parse("{" + messageJson + "}").message;
                    console.log("已获取魔王系统最新消息。");
                }

                // 计算位置
                const rect = assistantIcon.getBoundingClientRect();
                chatBubble.style.left = `${rect.right + 15}px`;
                chatBubble.style.top = `${rect.top + (rect.height / 2) - 20}px`;

                parentWin.document.body.appendChild(chatBubble);

                // 动画结束后自动移除，防止DOM残留
                setTimeout(() => {
                    const bubble = parentWin.document.getElementById(chatBubbleId);
                    if (bubble) {
                        bubble.parentNode.removeChild(bubble);
                    }
                }, 6000);
            }

            // 监听事件
            eventOn(tavern_events.MESSAGE_RECEIVED, showChatBubble);
            eventOn(tavern_events.MESSAGE_SWIPED, showChatBubble);
            console.log('[灵体赋声术] 咏唱成功！Albin已获得回应您的能力。');
            // 进入首页时就小精灵就说一句话
            showChatBubble(-1);
      });
    } else if (initAttempts > maxAttempts) {
      clearInterval(checkIntervalId);
      logError('初始化超时，未能加载SillyTavern核心API(特别是TavernHelper)。脚本将无法工作。');
    }
  }, checkInterval);

