            transition: left 0.5s cubic-bezier(0.23, 1, 0.32, 1);
        }
        .action-button:hover:not(:disabled) {
            background: linear-gradient(145deg, rgba(138, 77, 255, 0.3), rgba(138, 77, 255, 0.4));
            box-shadow: 0 0 15px var(--primary-glow-color);
            color: #fff;
            transform: translateY(-2px);
        }
        .action-button:hover:not(:disabled)::before { left: 100%; }
        .action-button:disabled {
            background: var(--disabled-color) !important;
            border-color: #444 !important;
            color: var(--disabled-text) !important;
            cursor: not-allowed !important;
            transform: none !important;
            box-shadow: none !important;
        }
        .action-button:disabled::before { display: none; }
        .action-button.back-button { border-color: var(--accent-glow-color); } /* 返回按钮特殊样式 */

        /* --- 地图模态框样式 --- */
        .map-modal-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.7); display: flex; justify-content: center; align-items: center; z-index: 100; opacity: 0; visibility: hidden; transition: opacity 0.3s ease, visibility 0s 0.3s; }
        .map-modal-overlay.visible { opacity: 1; visibility: visible; transition: opacity 0.3s ease; }
        .map-modal-content { width: 80%; height: 80%; transform: scale(0.9); transition: transform 0.3s ease; }
        .map-modal-overlay.visible .map-modal-content { transform: scale(1); }
        .map-area { height: 100%; display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(4, 1fr); grid-template-areas: "demon_realm demon_realm neutral_zone human_kingdom" "demon_realm demon_realm neutral_zone human_kingdom" "elf_forest elf_forest neutral_zone human_kingdom" "elf_forest elf_forest neutral_zone human_kingdom"; gap: 8px; background: rgba(0,0,0,0.3); border: 1px solid var(--border-color); padding: 8px; border-radius: 8px; }
        .faction-territory { display: flex; justify-content: center; align-items: center; font-weight: bold; font-family: var(--font-tech); text-shadow: 1px 1px 3px black; border-radius: 4px; cursor: pointer; transition: all 0.3s ease; text-align: center;}
        .faction-territory:hover { transform: scale(1.03); z-index: 10; }
        .close-map-btn { position: absolute; top: 20px; right: 20px; font-size: 2em; color: white; cursor: pointer; text-shadow: 0 0 10px black; transition: transform 0.2s; }
        .close-map-btn:hover { transform: scale(1.2) rotate(90deg); }

        /* --- 其他组件样式 (省略大部分未变动的) --- */
        .character-list-container { display: flex; gap: 20px; align-items: center; overflow-x: auto; width: 100%; padding-bottom: 10px; }
        .character-card { display: flex; background-color: rgba(40, 30, 70, 0.7); padding: 15px; border-radius: 10px; border: 1px solid var(--border-color); min-width: 300px; flex-shrink: 0; }
        .char-avatar-wrapper { width: 80px; height: 80px; margin-right: 20px; flex-shrink: 0; }
        .char-avatar { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; border: 3px solid var(--primary-glow-color); }
        .char-info h4 { margin: 0 0 10px 0; padding: 0; border: none; color: #fff; }
        .log-display::-webkit-scrollbar, .action-list::-webkit-scrollbar, .location-panel ul::-webkit-scrollbar { width: 8px; }
        .log-display::-webkit-scrollbar-track, .action-list::-webkit-scrollbar-track, .location-panel ul::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }
        .log-display::-webkit-scrollbar-thumb, .action-list::-webkit-scrollbar-thumb, .location-panel ul::-webkit-scrollbar-thumb { background: var(--primary-glow-color); border-radius: 4px; }
        .global-toast { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); background: linear-gradient(135deg, var(--accent-glow-color), var(--primary-glow-color)); color: white; padding: 12px 25px; border-radius: 8px; z-index: 1000; box-shadow: 0 4px 15px rgba(0,0,0,0.4); animation: toast-in-out 3.5s ease; }
        @keyframes toast-in-out { 0% { opacity: 0; transform: translate(-50%, 20px); } 15% { opacity: 1; transform: translate(-50%, 0); } 85% { opacity: 1; transform: translate(-50%, 0); } 100% { opacity: 0; transform: translate(-50%, 20px); } }
    </style>
</head>
<body>
    <div id="particles-js"></div>
    <div id="app" :class="{ 'map-visible': uiState.isMapVisible }">
        </div>
<script src="https://cdn.jsdelivr.net/npm/particles.js@2.0.0/particles.min.js"></script>
<script>
    particlesJS("particles-js", {
            "particles": {
                "number": {
                "value": 80, // 粒子数量
                "density": {
                    "enable": true,
                    "value_area": 800 // 粒子分布区域密度
                }
                },
                "color": {
                "value": "#8a4dff" // 粒子颜色：深邃的紫色
                },
                "shape": {
                "type": "circle", // 粒子形状
                "stroke": {
                    "width": 0,
                    "color": "#000000"
                }
                },
                "opacity": {
                "value": 0.5, // 粒子不透明度
                "random": true, // 不透明度随机
                "anim": {
                    "enable": true, // 开启不透明度渐变动画
                    "speed": 0.8,
                    "opacity_min": 0.1,
                    "sync": false
                }
                },
                "size": {
                "value": 3, // 粒子大小
                "random": true, // 大小随机
                "anim": {
                    "enable": false // 关闭大小动画
                }
                },
                "line_linked": {
                "enable": true, // 开启粒子间连线
                "distance": 150, // 连线触发距离
                "color": "#8a4dff", // 连线颜色
                "opacity": 0.3, // 连线不透明度
                "width": 1
                },
                "move": {
                "enable": true,
                "speed": 1.5, // 粒子移动速度
                "direction": "none",
                "random": true, // 移动方向随机
                "straight": false,
                "out_mode": "out", // 粒子移出边界后的行为
                "bounce": false
                }
            },
            "interactivity": {
                "detect_on": "canvas",
                "events": {
                "onhover": {
                    "enable": true,
                    "mode": "grab" // 鼠标悬停时抓住粒子
                },
                "onclick": {
                    "enable": true,
                    "mode": "push" // 鼠标点击时推开粒子
                },
                "resize": true
                },
                "modes": {
                "grab": {
                    "distance": 140,
                    "line_linked": {
                    "opacity": 1
                    }
                },
                "push": {
                    "particles_nb": 4 // 点击时推出的粒子数量
                }
                }
            },
            "retina_detect": true
            }
        );

    const { createApp, reactive, computed, nextTick, ref } = Vue;

    const app = createApp({
        template: `
            <div v-if="snapshot.uiEvents" class="global-toast">{{ getToastMessage() }}</div>
            <!-- <div v-if="uiState.toast.message" class="global-toast">{{ uiState.toast.message }}</div> -->
            <div class="map-modal-overlay" :class="{ 'visible': uiState.isMapVisible }" @click.self="uiState.isMapVisible = false">
                <div class="map-modal-content game-panel">
                    <span class="close-map-btn" @click="uiState.isMapVisible = false">&times;</span>
                    <div class="map-area">
                        <div v-for="faction in snapshot.worldState.factions" class="faction-territory" :style="{ 'background': faction.color }">{{ faction.name }}</div>
                    </div>
                </div>
            </div>

            <div class="game-panel info-panel">
                <h3 class="panel-header">{{ snapshot.infoPanelContent.title }}</h3>

                <div class="info-display" ref="infoDisplay">
                    <div v-for="(section, index) in snapshot.infoPanelContent.sections" :key="index" class="info-section">
                        <h4>{{ section.header }}</h4>
                        <p v-html="section.content"></p>
                    </div>
                </div>
            </div>

            <div class="right-panels">
                 <div class="game-panel resource-panel">
                    <h3 class="panel-header">资源状况</h3>
                    <ul><li v-for="(v, k) in snapshot.playerState.resources"><span>{{getResourceName(k)}}:</span><span class="resource-value">{{v}}</span></li></ul>
                </div>
                <div class="game-panel location-panel">
                    <h3 class="panel-header">{{ snapshot.context.location.name }}</h3>
                    <p class="description">{{ snapshot.context.location.description }}</p>
                    <ul><li v-for="b in snapshot.context.location.buildings" @click="handleLocalAction({type: 'select_building', id: b.id})">{{b.name}} ({{b.status}})</li></ul>
                </div>
                 <div class="game-panel action-panel">
                    <h3 class="panel-header">
                        {{ uiState.actionTitle }}
                        <!-- <div class="panel-header-breadcrumb">{{ breadcrumb }}</div> -->
                    </h3>
                    <transition name="action-list" mode="out-in">
                        <ul class="action-list" :key="uiState.viewPath.join('>')">
                            <li v-for="button in currentActions" :key="button.id">
                                <button @click="handleActionClick(button)" :disabled="isButtonDisabled(button)" class="action-button" :class="button.style_class" :title="button.overview">
                                    {{ button.name }} <small v-if="button.costText">({{ button.costText }})</small>
                                </button>
                            </li>
                            <!-- 返回按钮现在由计算属性动态添加 -->
                        </ul>
                    </transition>
                </div>
            </div>
            <div class="game-panel character-panel">
                <div class="character-list-container">
                    <div v-for="char in snapshot.playerState.characters" :key="char.id" class="character-card">
                        <div class="char-avatar-wrapper"><img :src="char.avatar" :alt="char.name" class="char-avatar"></div>
                        <div class="char-info">
                            <h4>{{ char.name }} <small>({{ char.title }})</small></h4>
                            <div v-if="char.stats" class="char-stats">
                                <span class="stat-item affinity">
                                    好感: {{ char.stats.affinity }}
                                </span>
                                <span class="stat-item corruption">
                                    堕落: {{ char.stats.corruption }}
                                </span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `,
        setup() {
            // --- 状态管理 ---
            const isWaitingForAI = ref(false);
            const logDisplay = ref(null);
            const snapshot = reactive($1);

            // 本地UI状态，现在使用路径数组来管理视图
            const uiState = reactive({
                isMapVisible: false,
                viewPath: ['root'], // 'root' -> 'management_module' -> 'construction'
                toast: { message: '', timer: null },
            });

            // --- 计算属性 ---
            const getResourceName = (key) => ({ magicCrystal: '魔晶', soulEssence: '魂魄', corruptionEssence: '堕落精华' }[key] || key);

            // --- 计算属性 ---
            const breadcrumb = computed(() => uiState.viewPath.join(' > '));

            const currentActions = computed(() => {
                let currentLevel = snapshot.context.actions;
                let pathIndex = 1;

                while (pathIndex < uiState.viewPath.length) {
                    const nextViewId = uiState.viewPath[pathIndex];
                    const nextLevel = currentLevel.buttons.find(b => b.id === nextViewId);
                    if (nextLevel && nextLevel.sub_categories) {
                        currentLevel = { buttons: nextLevel.sub_categories.map(sc => ({...sc, type: 'ui_category'})) };
                    } else if (nextLevel && nextLevel.buttons) {
                         currentLevel = { buttons: nextLevel.buttons };
                    } else {
                        // 如果路径无效，返回根目录
                         return snapshot.context.actions.buttons;
                    }
                    pathIndex++;
                }

                const actions = [...currentLevel.buttons];
                if(uiState.viewPath.length > 1) {
                    actions.push({id: 'back_to_previous', name: '<< 返回', type: 'ui_back'});
                }
                return actions;
            });

            uiState.actionTitle = computed(() => {
                const currentViewId = uiState.viewPath[uiState.viewPath.length - 1];
                if (currentViewId === 'root') {
                    return "行动决策";
                }

                let currentLevel = { buttons: snapshot.context.actions.buttons };
                let title = "行动决策";
                let found = false;

                for (let i = 1; i < uiState.viewPath.length; i++) {
                    const viewId = uiState.viewPath[i];
                    found = false;
                    if (currentLevel.buttons) {
                        const nextLevel = currentLevel.buttons.find(b => b.id === viewId);
                        if (nextLevel) {
                            title = nextLevel.name;
                            currentLevel = { buttons: nextLevel.sub_categories?.map(sc => ({...sc, type: 'ui_category'})) || nextLevel.buttons };
                            found = true;
                        }
                    }
                    if (!found) break; // If path is broken, stop.
                }
                return title;
            });


            // --- 方法 ---
            const getToastMessage = () => {
                if (!snapshot.uiEvents) return '';
                const toastEvent = snapshot.uiEvents.find(e => e.type === 'SHOW_TOAST');
                return toastEvent ? toastEvent.payload.message : '';
            };

            /* ... 资源检查逻辑 ... */ 
            const isButtonDisabled = (button) => {
                if (isWaitingForAI.value) {
                        return true;
                }

                // 首先，检查按钮本身是否在数据中就被标记为禁用
                if (button.disabled) {
                    return true;
                }

                // 检查是否有资源消耗定义
                if (!button.costText) { // 我们以costText作为有消耗的标志
                    return false; // 没有消耗，永远不会因资源不足而禁用
                }

                // 解析costText字符串以获取消耗
                // 这是一个简化的解析，未来可由更标准的cost对象代替
                // 例如 "魔晶200, 魂魄20"
                const costs = button.costText.split(',');
                for (const costStr of costs) {
                    const trimmedCost = costStr.trim();
                    if (trimmedCost.includes('魔晶')) {
                        const amount = parseInt(trimmedCost.replace(/[^0-9]/g, ''));
                        if (snapshot.playerState.resources.magicCrystal < amount) return true;
                    } else if (trimmedCost.includes('魂魄')) {
                        const amount = parseInt(trimmedCost.replace(/[^0-9]/g, ''));
                        if (snapshot.playerState.resources.soulEssence < amount) return true;
                    } else if (trimmedCost.includes('堕落精华')) {
                        const amount = parseInt(trimmedCost.replace(/[^0-9]/g, ''));
                        if (snapshot.playerState.resources.corruptionEssence < amount) return true;
                    }
                }

                // 如果所有资源检查都通过，则按钮可用
                return false;
            };

            const sendToAI = (payload) => {
                if (isWaitingForAI.value) return;
                isWaitingForAI.value = true;
                console.log("向AI发送指令:", payload);
                // 这里是与sillytavern_connector.js通信的地方
                // parent.postMessage({ type: 'DEMON_KING_ACTION', payload }, '*');
                // 调用sillytavern指令
                triggerSlash('/send ' + '[玩家指令] 类型: ' + payload.type + ', 目标: ' + payload.id + '|/trigger');
            };

            const handleActionClick = (button) => {
                const buttonType = button.type || 'action';

                switch(buttonType) {
                    case 'ui_static':
                        if (button.id === 'open_map') uiState.isMapVisible = true;
                        break;
                    case 'ui_category': // 进入下一级（从模块到次级分类）
                    case 'category': // 进入下一级（从根到模块）
                        uiState.viewPath.push(button.id);
                        break;
                    case 'ui_back':
                        uiState.viewPath.pop();
                        break;
                    case 'action':
                    default:
                        sendToAI({ type: buttonType , id: button.id, name: button.name });
                        break;
                }
            };

            // --- AI数据更新 ---
            window.addEventListener('message', (event) => {
                if (event.data && event.data.type === 'UPDATE_DEMON_KING_UI') {
                    // ... 更新snapshot数据的代码 ...

                    // [!] 核心修改：在UI更新完毕后，宣告世界“沉思”结束，解除所有按钮的锁定
                    isWaitingForAI.value = false;
                }
            });

            return { snapshot, uiState, isWaitingForAI, logDisplay, breadcrumb, currentActions, handleActionClick, getResourceName, isButtonDisabled, getToastMessage/* ... */ };
        }
    }).mount('#app');
</script>
</body>
</html>
```
